CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value INTEGER NOT NULL);
INSERT OR IGNORE INTO metadata VALUES ('revision', 1);
CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, household_id TEXT REFERENCES households(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('caregiver','operator')), created_at REAL NOT NULL, household_role TEXT CHECK(household_role IN ('owner','caregiver','viewer')), team_role TEXT CHECK(team_role IN ('admin','support')));
CREATE TABLE IF NOT EXISTS devices (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('simulator','physical')), token_hash TEXT UNIQUE, last_seen REAL, connected INTEGER NOT NULL DEFAULT 0, battery REAL, charging INTEGER, sensor_ok INTEGER, clock_ok INTEGER, queue_overflow INTEGER NOT NULL DEFAULT 0, firmware TEXT NOT NULL DEFAULT 'not connected', escalation_seconds INTEGER NOT NULL DEFAULT 60, created_at REAL NOT NULL, offline_alert_seconds INTEGER NOT NULL DEFAULT 900);
CREATE TABLE IF NOT EXISTS gateways (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('web','phone','hub')), token_hash TEXT NOT NULL UNIQUE, created_at REAL NOT NULL, last_seen REAL, connected INTEGER NOT NULL DEFAULT 0, app_version TEXT, revoked_at REAL);
CREATE TABLE IF NOT EXISTS reminders (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), label TEXT NOT NULL, minute INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at REAL NOT NULL, effective_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS contacts (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), name TEXT NOT NULL, email TEXT NOT NULL, priority INTEGER NOT NULL, phone TEXT, UNIQUE(device_id,email));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), device_id TEXT NOT NULL REFERENCES devices(id), kind TEXT NOT NULL, status TEXT NOT NULL, source_ref TEXT, occurred_at REAL, received_at REAL NOT NULL, due_at REAL, escalation_level INTEGER NOT NULL DEFAULT 0, note TEXT NOT NULL DEFAULT '', acknowledged_at REAL, UNIQUE(device_id,source_ref));
CREATE TABLE IF NOT EXISTS ingested (device_id TEXT NOT NULL REFERENCES devices(id), source_id TEXT NOT NULL, received_at REAL NOT NULL, PRIMARY KEY(device_id,source_id));
CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY, device_id TEXT NOT NULL REFERENCES devices(id), event_id TEXT NOT NULL REFERENCES events(id), expires_at REAL NOT NULL, received_at REAL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), event_id TEXT NOT NULL REFERENCES events(id), recipient TEXT NOT NULL, channel TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, next_try REAL, created_at REAL NOT NULL, completed_at REAL, error TEXT, UNIQUE(event_id,recipient,channel));
CREATE TABLE IF NOT EXISTS api_tokens (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, created_at REAL NOT NULL, last_used REAL, expires_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS invites (code_hash TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), role TEXT NOT NULL CHECK(role IN ('caregiver','viewer')), created_by TEXT NOT NULL REFERENCES users(id), created_at REAL NOT NULL, expires_at REAL NOT NULL, used_by TEXT REFERENCES users(id), used_at REAL);
CREATE TABLE IF NOT EXISTS push_tokens (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), platform TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS inventory (serial TEXT PRIMARY KEY, hardware_rev TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('in_stock','assigned','returned','faulty','retired')), device_id TEXT UNIQUE REFERENCES devices(id), notes TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL, updated_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS support_notes (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, created_at REAL NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, at REAL NOT NULL);
CREATE INDEX IF NOT EXISTS devices_household ON devices(household_id);
CREATE INDEX IF NOT EXISTS gateways_device ON gateways(device_id);
CREATE INDEX IF NOT EXISTS events_household_time ON events(household_id,received_at DESC);
CREATE INDEX IF NOT EXISTS events_due ON events(status,due_at);
CREATE INDEX IF NOT EXISTS notifications_household_time ON notifications(household_id,created_at DESC);
CREATE INDEX IF NOT EXISTS notifications_retry ON notifications(status,next_try);
CREATE INDEX IF NOT EXISTS reminders_device ON reminders(device_id);
CREATE INDEX IF NOT EXISTS commands_device ON commands(device_id,received_at);
CREATE INDEX IF NOT EXISTS api_tokens_user ON api_tokens(user_id);
CREATE INDEX IF NOT EXISTS push_tokens_user ON push_tokens(user_id);
CREATE INDEX IF NOT EXISTS notes_household ON support_notes(household_id,created_at DESC);
